def calculate(n):
    N = 2 * n
    # Initialize 3D DP array with zeros
    dp = [[[0 for _ in range(2)] for _ in range(N + 1)] for _ in range(N + 1)]
    # Base case
    dp[0][0][0] = 0
    for i in range(1, N + 1):
        for j in range(0, i + 1):
            for k in range(2):
                if k == 1:
                    if i - j >= 2:
                        dp[i][j][k] = add(dp[i][j][k], dp[i - 1][j + 1][0], MOD)
                    if j > 0:
                        dp[i][j][k] = add(dp[i][j][k], dp[i - 1][j - 1][0], MOD)
                else:
                    val1 = getVal(dp, i, j, False, False, MOD)
                    val2 = getVal(dp, i, j, False, True, MOD)
                    val3 = getVal(dp, i, j, True, False, MOD)
                    dp[i][j][k] = max(val1, max(val2, val3))
    return dp[N][0][0]

def getVal(dp, i, j, selectStart, selectEnd, MOD):
    res = 0
    if i - j >= 2:
        if selectStart:
            res = add(res, dp[i - 1][j + 1][1], MOD)
            res = add(res, 1, MOD)
        else:
            res = add(res, dp[i - 1][j + 1][0], MOD)
    if j > 0:
        if selectEnd:
            res = add(res, dp[i - 1][j - 1][1], MOD)
            res = add(res, 1, MOD)
        else:
            res = add(res, dp[i - 1][j - 1][0], MOD)
    return res

def add(a, b, MOD):
    res = a + b
    if res >= MOD:
        res -= MOD
    return res

